from ute_common_abstract_core.network_elem_identification import MsgSourceIdentification
from ute_common_abstract_core.network_elem_identification import CellIdentification
from ...ltecell import LteCell


class DemoCell(LteCell):
    """Iphy cell object"""

    def __init__(self, identification):
        """

        :param identification: encapsulated CELL description
        :type: CellIdentification
        """
        all_ids = list(identification.items())
        all_ids.append(('demo', identification['infomodel']))
        demo_cell_id = CellIdentification.from_type_id_pairs(identifiers=all_ids, specific_for_tool='demo')
        super().__init__(demo_cell_id)
        MsgSourceIdentification(identifiers=[('demo', self.get_cell_id())], network_elem_type='CELL', specific_for_tool='demo')
